struct TlRec0 {
    f_name: String,
}

fn tl_parse_rec0(p: &mut TlParser) -> TlRec0 {
    let mut f_name: Option<String> = None;
    p.expect(b'{');
    if !p.at(b'}') {
        loop {
            let key = tl_parse_str(p);
            p.expect(b':');
            match key.as_str() {
                "name" => f_name = Some((tl_parse_str)(p)),
                _ => p.skip_value(),
            }
            if p.at(b',') { p.p += 1; continue; }
            break;
        }
    }
    p.expect(b'}');
    TlRec0 {
        f_name: f_name.unwrap_or_else(|| tl_fail("missing field `name`")),
    }
}

fn v_get_name(v_db: TlRec0) -> String {
    v_db.clone().f_name
}

fn main() {
    let t_input: TlRec0 = tl_read_value(tl_parse_rec0);
    println!("{}", v_get_name(t_input.clone()));
